 const sets={styles:[0,1,2,3,4,5,6,7,11,12,13,14],kpop:[8,9,10],toy:[15,16],disney:[0,1,2,3,4,5],equestria:[6,7,8,9,10,11]};
 if(sets[current]){const chars=['disney','equestria'].includes(current);$('#menu-content').innerHTML=`<div class="illustrated-menu ready-menu">${sets[current].map(i=>`<button class="illustrated-card" data-ready="${i}"><span class="menu-art" aria-hidden="true">${avatar(chars?characterLook(i,{...fashionDefault,tints:{}}):presetLook(i),false)}</span><span>${chars?characterModels[i].name:presetNames[i]}</span></button>`).join('')}</div>`;document.querySelectorAll('[data-ready]').forEach(b=>b.onclick=()=>{look=chars?characterLook(+b.dataset.ready,look):presetLook(+b.dataset.ready);faceZoom=false;drawFashion();chime();notify('Look escolhido! Você pode continuar personalizando.')});return}
